function applySettings(){document.body.classList.toggle('dark',settings.theme==='dark');document.body.classList.toggle('reduce-motion',!settings.motion);document.documentElement.style.setProperty('--accent',settings.accent);const m=/^#([0-9a-f]{2})([0-9a-f]{2})([0-9a-f]{2})$/i.exec(settings.accent);if(m)document.documentElement.style.setProperty('--accent-rgb',[1,2,3].map(i=>parseInt(m[i],16)).join(','));document.documentElement.style.setProperty('--dockSize',settings.dockSize+'px');$('#wallpaper').className='wallpaper '+(settings.wallpaper==='scenic'?'':settings.wallpaper);$('#dock').style.setProperty('--dockSize',settings.dockSize+'px');store('settings',settings)}
