function openApp(id,opts={}){if(!definitions[id])return;let w=windows.get(id);if(w){focusWindow(id);if(id==='textedit'&&opts.fileId)renderTextEdit(opts);if(id==='finder'&&opts.folder)navigateFolder(opts.folder);return w}const d=definitions[id],offset=windows.size*23,vw=innerWidth,vh=innerHeight,width=Math.min(d.size[0],vw-32),height=Math.min(d.size[1],vh-130);w=document.createElement('section');w.className='window';w.dataset.app=id;w.style.width=width+'px';w.style.height=height+'px';w.style.left=Math.max(5,(vw-width)/2-60+(offset%160))+'px';w.style.top=Math.max(4,(vh-32-height)/2-20+(offset%116))+'px';w.innerHTML=`<div class="window-bar"><div class="traffic"><button class="close" title="Close" aria-label="Close"></button><button class="min" title="Minimize" aria-label="Minimize"></button><button class="max" title="Maximize" aria-label="Maximize"></button></div><span class="window-title">${ic(d.icon)}${esc(d.name)}</span></div><div class="window-body"></div>`;$('#window-layer').appendChild(w);windows.set(id,w);w.addEventListener('pointerdown',()=>focusWindow(id));w.querySelector('.close').onclick=e=>{e.stopPropagation();closeWindow(id)};w.querySelector('.min').onclick=e=>{e.stopPropagation();w.classList.add('minimized');renderDock()};w.querySelector('.max').onclick=e=>{e.stopPropagation();w.classList.toggle('maximized')};w.querySelector('.window-bar').ondblclick=e=>{if(!e.target.closest('.traffic'))w.classList.toggle('maximized')};initDrag(w);focusWindow(id);renderApp(id,opts);return w}
function initDrag(w){const bar=w.querySelector('.window-bar');let drag=null;bar.addEventListener('pointerdown',e=>{if(e.target.closest('button')||w.classList.contains('maximized')||innerWidth<730)return;drag={x:e.clientX,y:e.clientY,l:w.offsetLeft,t:w.offsetTop};bar.setPointerCapture(e.pointerId)});bar.addEventListener('pointermove',e=>{if(!drag)return;w.style.left=Math.max(0,Math.min(innerWidth-w.offsetWidth/3,drag.l+e.clientX-drag.x))+'px';w.style.top=Math.max(0,Math.min(innerHeight-140,drag.t+e.clientY-drag.y))+'px'});bar.addEventListener('pointerup',()=>drag=null);bar.addEventListener('pointercancel',()=>drag=null)}
