function renderTextEdit(opts={}){const b=body('textedit');if(!b)return;if(opts.fileId)editingFileId=opts.fileId;let f=fs.find(x=>x.id===editingFileId&&!x.trashed);if(!f){f=fs.find(x=>x.id==='welcome');editingFileId=f?.id}b.innerHTML=`<div class="window-toolbar"><strong class="grow ellipsis" id="edit-filename">${esc(f?.name||'Untitled')}</strong><span class="muted small" id="edit-saved">Saved locally</span><button class="secondary-button" id="edit-saveas">Save As</button><button class="icon-button" id="edit-download" title="Download">${ic('download')}</button></div><textarea id="textedit-field" spellcheck="false" class="soft-textarea scroll" style="padding:25px 30px;flex:1;font:13px/1.8 SFMono-Regular,Consolas,monospace" aria-label="Text file editor">${esc(f?.content||'')}</textarea>`;const editor=b.querySelector('#textedit-field');editor.oninput=()=>{if(!f)return;f.content=editor.value;f.created=Date.now();saveFS();b.querySelector('#edit-saved').textContent='Saved just now'};b.querySelector('#edit-saveas').onclick=()=>{let name=askName('Save as:',f?.name||'Untitled.txt');if(name){const copy=addFile(name,'text',editor.value,'Documents');if(copy){editingFileId=copy.id;renderTextEdit({fileId:copy.id})}}};b.querySelector('#edit-download').onclick=()=>downloadText(f?.name||'Untitled.txt',editor.value)};
