let notes=load('notes',[{id:uid(),title:'A fresh beginning',body:'A little space for your big ideas.\n\nNotes are automatically saved here on this device.\n\nTry creating a new note with the + button.',updated:Date.now()}]);let noteId=notes[0]?.id||null;const saveNotes=()=>store('notes',notes);
function renderNotes(){const b=body('notes');if(!b)return;const note=notes.find(n=>n.id===noteId);b.innerHTML=`<div class="window-toolbar"><div class="grow"><strong>My Notes</strong><span class="muted small" style="margin-left:9px">${notes.length} notes</span></div><button class="icon-button" id="note-new" title="New note">${ic('plus')}</button><button class="icon-button" id="note-trash" title="Delete note" ${!note?'disabled':''}>${ic('trash')}</button><button class="icon-button" id="note-export" title="Export note" ${!note?'disabled':''}>${ic('download')}</button></div><div class="window-pane"><aside class="app-sidebar" style="width:240px"><div class="sidebar-heading">ALL NOTES</div>${notes.slice().sort((a,b)=>b.updated-a.updated).map(n=>`<div class="note-list-item ${noteId===n.id?'active':''}" data-note="${n.id}"><strong>${esc(n.title||'Untitled Note')}</strong><div class="note-preview">${esc(n.body.replace(/\s+/g,' ').slice(0,60)||'Empty note')}</div></div>`).join('')}</aside><main class="app-main">${note?`<div style="padding:28px 34px;height:100%;display:flex;flex-direction:column"><input id="note-title-field" class="note-title" placeholder="Title" value="${esc(note.title)}"><div class="muted small" style="margin-bottom:15px">${new Date(note.updated).toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric',year:'numeric'})} · Autosaves</div><textarea id="note-content-field" class="soft-textarea note-editor scroll" placeholder="Start writing...">${esc(note.body)}</textarea></div>`:`<div class="empty-state">${ic('note')}<h3>Start with a note</h3><p>Click + to capture a thought.</p></div>`}</main></div>`;b.querySelectorAll('[data-note]').forEach(el=>el.onclick=()=>{noteId=el.dataset.note;renderNotes()});b.querySelector('#note-new').onclick=()=>{const n={id:uid(),title:'Untitled Note',body:'',updated:Date.now()};notes.unshift(n);noteId=n.id;saveNotes();renderNotes();b.querySelector('#note-title-field')?.focus()};b.querySelector('#note-trash').onclick=()=>{if(!note||!confirm('Delete this note?'))return;notes=notes.filter(n=>n.id!==note.id);noteId=notes[0]?.id||null;saveNotes();renderNotes()};b.querySelector('#note-export').onclick=()=>{if(note)downloadText((note.title||'Note')+'.txt',note.body)};if(note){const update=()=>{note.title=b.querySelector('#note-title-field').value;note.body=b.querySelector('#note-content-field').value;note.updated=Date.now();saveNotes();const list=b.querySelector(`[data-note="${note.id}"]`);if(list){list.querySelector('strong').textContent=note.title||'Untitled Note';list.querySelector('.note-preview').textContent=note.body.slice(0,55)}};b.querySelector('#note-title-field').oninput=update;b.querySelector('#note-content-field').oninput=update}}
