let browserTabs=[{id:uid(),title:'Start Page',url:'',mode:'start',entries:[{url:'',mode:'start',title:'Start Page'}],pos:0}],browserTab=browserTabs[0].id;let browserCache={};
function currentTab(){return browserTabs.find(t=>t.id===browserTab)||browserTabs[0]}
function addTab(url=''){const t={id:uid(),title:'Start Page',url:'',mode:'start',entries:[{url:'',mode:'start',title:'Start Page'}],pos:0};browserTabs.push(t);browserTab=t.id;if(url)navBrowser(url);else renderBrowser()}
function browserGoEntry(url,mode,title){const t=currentTab();t.url=url;t.mode=mode;t.title=title||url||'Start Page';t.entries=t.entries.slice(0,t.pos+1);t.entries.push({url,mode,title:t.title});t.pos=t.entries.length-1;renderBrowser()}
function navBrowser(raw){let input=String(raw||'').trim();if(!input)return browserGoEntry('','start','Start Page');if(input.startsWith('wiki:'))return browserGoEntry(input.slice(5),'wiki-search','Search: '+input.slice(5));if(input.startsWith('search:')){openExternal('https://www.google.com/search?q='+encodeURIComponent(input.slice(7)));return}if(!/^https?:\/\//i.test(input)&&!/^(localhost|\d{1,3}(\.\d{1,3}){3})(:\d+)?(\/|$)/i.test(input)&&(!input.includes('.')||input.includes(' '))){browserGoEntry(input,'wiki-search','Search: '+input);return}if(!/^https?:\/\//i.test(input))input='https://'+input;let url;try{url=new URL(input)}catch{notify('Invalid URL');return}if(!['https:','http:'].includes(url.protocol)){notify('Only web addresses (http/https) are supported');return}browserGoEntry(url.href,'iframe',url.hostname.replace(/^www\./,''))}
