let bookmarks=load('bookmarks',[{title:'Wikipedia',url:'https://en.wikipedia.org'},{title:'MDN Web Docs',url:'https://developer.mozilla.org'}]);let browserHistory=load('webhistory',[]);
function renderBrowser(){const b=body('browser');if(!b)return;const t=currentTab();b.innerHTML=`<div class="browser-tabs">${browserTabs.map(x=>`<div class="browser-tab ${x.id===t.id?'active':''}" data-tab="${x.id}">${ic('compass','tiny-icon')}<span class="tab-name">${esc(x.title)}</span><button class="tab-close" data-close-tab="${x.id}" title="Close tab">${ic('x','tiny-icon')}</button></div>`).join('')}<button class="icon-button" id="browser-new-tab" title="New tab">${ic('plus')}</button></div><div class="browser-controls"><button class="icon-button" id="browser-back" title="Back" ${t.pos===0?'disabled':''}>${ic('chevronLeft')}</button><button class="icon-button" id="browser-next" title="Forward" ${t.pos>=t.entries.length-1?'disabled':''}>${ic('chevronRight')}</button><button class="icon-button" id="browser-home" title="Home">${ic('home')}</button><form class="url-field" id="browser-address-form">${ic('lock')}<input id="browser-address" aria-label="Web address or encyclopedia search" autocomplete="off" spellcheck="false" placeholder="Search Wikipedia or enter a URL" value="${esc(t.url)}"></form><button class="icon-button" id="browser-reload" title="Reload">${ic('refresh')}</button><button class="icon-button" id="browser-bookmark" title="Bookmark this page">${ic('star')}</button><button class="icon-button" id="browser-external" title="Open page in your real browser">${ic('external')}</button></div><div class="browser-viewport" id="browser-viewport"></div><div class="browser-status" id="browser-status">${t.mode==='iframe'?'Website preview · Some sites block embedded browsing · ↗ opens the real browser':t.mode.startsWith('wiki')?'Reader powered by Wikipedia · ↗ opens source':'Search Wikipedia inside Golden Gate OS, or use a real browser to search the whole web'}</div>`;
b.querySelectorAll('[data-tab]').forEach(el=>el.onclick=e=>{if(e.target.closest('[data-close-tab]'))return;browserTab=el.dataset.tab;renderBrowser()});b.querySelectorAll('[data-close-tab]').forEach(el=>el.onclick=e=>{e.stopPropagation();if(browserTabs.length===1){browserTabs=[{id:uid(),title:'Start Page',url:'',mode:'start',entries:[{url:'',mode:'start',title:'Start Page'}],pos:0}];browserTab=browserTabs[0].id}else{browserTabs=browserTabs.filter(x=>x.id!==el.dataset.closeTab);if(browserTab===el.dataset.closeTab)browserTab=browserTabs.at(-1).id}renderBrowser()});b.querySelector('#browser-new-tab').onclick=()=>addTab();b.querySelector('#browser-back').onclick=()=>{if(t.pos>0){t.pos--;Object.assign(t,t.entries[t.pos]);renderBrowser()}};b.querySelector('#browser-next').onclick=()=>{if(t.pos<t.entries.length-1){t.pos++;Object.assign(t,t.entries[t.pos]);renderBrowser()}};b.querySelector('#browser-home').onclick=()=>navBrowser('');b.querySelector('#browser-reload').onclick=()=>renderBrowser();b.querySelector('#browser-address-form').onsubmit=e=>{e.preventDefault();navBrowser(b.querySelector('#browser-address').value)};b.querySelector('#browser-external').onclick=()=>{if(t.mode==='iframe')openExternal(t.url);else if(t.mode.startsWith('wiki'))openExternal('https://en.wikipedia.org/wiki/'+encodeURIComponent(t.url));else openExternal('https://www.google.com')};b.querySelector('#browser-bookmark').onclick=()=>{if(!t.url){notify('Open a page first');return}const url=t.mode==='iframe'?t.url:'https://en.wikipedia.org/wiki/'+encodeURIComponent(t.url);bookmarks.push({title:t.title,url});store('bookmarks',bookmarks);notify('Bookmark saved')};
const v=b.querySelector('#browser-viewport');if(t.mode==='start'){v.innerHTML=`<div class="browser-start"><div class="browser-logo">${ic('compass')}</div><h2>Go somewhere new.</h2><p>The web, thoughtfully within reach.</p><form class="browser-search" id="wiki-search-form"><input class="soft-input" id="wiki-search-input" placeholder="Search Wikipedia, or enter a URL..." aria-label="Search"><button class="primary-button">Explore</button></form><div style="display:flex;justify-content:center;gap:10px;margin:12px auto"><button class="secondary-button" id="web-search-external">${ic('external','tiny-icon')} Search the full web</button></div><div class="eyebrow" style="max-width:600px;margin:24px auto 0">Favorites & destinations</div><div class="browser-link-grid">${[['Wikipedia','W','https://en.wikipedia.org'],['Google','G','https://www.google.com'],['YouTube','▶','https://www.youtube.com'],['MDN Docs','{ }','https://developer.mozilla.org'],['OpenStreetMap','⌖','https://www.openstreetmap.org'],['Internet Archive','▤','https://archive.org'],['Open-Meteo','☀','https://open-meteo.com'],['Example.com','e','https://example.com']].map(([title,letter,url])=>`<button class="site-card" data-site="${esc(url)}"><span class="site-favicon">${esc(letter)}</span><span>${esc(title)}</span></button>`).join('')}</div>${bookmarks.length?`<div style="max-width:600px;margin:auto"><div class="eyebrow">Your bookmarks</div><div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:11px">${bookmarks.slice(-8).map(o=>`<button class="secondary-button" data-site="${esc(o.url)}">${esc(o.title)}</button>`).join('')}</div></div>`:''}</div>`;v.querySelector('#wiki-search-form').onsubmit=e=>{e.preventDefault();navBrowser(v.querySelector('#wiki-search-input').value)};v.querySelector('#web-search-external').onclick=()=>{let q=v.querySelector('#wiki-search-input').value.trim();openExternal('https://www.google.com/search?q='+encodeURIComponent(q))};v.querySelectorAll('[data-site]').forEach(el=>el.onclick=()=>navBrowser(el.dataset.site))}
else if(t.mode==='iframe'){v.innerHTML=`<iframe class="browser-frame" id="embedded-web" title="Web page preview" referrerpolicy="strict-origin-when-cross-origin" sandbox="allow-scripts allow-forms allow-same-origin allow-popups allow-popups-to-escape-sandbox allow-downloads" src="${esc(t.url)}"></iframe><div class="browser-notice" id="browser-preview-notice"><span>Page blank? This website may prohibit embedding.</span><button id="preview-external">Open ↗</button><button id="notice-dismiss" aria-label="Dismiss">×</button></div>`;v.querySelector('#preview-external').onclick=()=>openExternal(t.url);v.querySelector('#notice-dismiss').onclick=()=>v.querySelector('#browser-preview-notice').remove();browserHistory.unshift({title:t.title,url:t.url,date:Date.now()});browserHistory=browserHistory.slice(0,35);store('webhistory',browserHistory)}
else if(t.mode==='wiki-search'){renderWikiSearch(v,t.url,t.id)}else if(t.mode==='wiki-article'){renderWikiArticle(v,t.url,t.id)} }
async function wikiRequest(query){const u='https://en.wikipedia.org/w/api.php?'+new URLSearchParams({...query,action:'query',format:'json',formatversion:'2',origin:'*'});const r=await fetch(u);if(!r.ok)throw Error('Wikipedia request failed');return r.json()}
async function renderWikiSearch(v,q,id){v.innerHTML=`<div class="panel-pad" style="max-width:760px;margin:0 auto"><div class="eyebrow">ENCYCLOPEDIA</div><h2 class="section-title" style="margin-top:9px">Search results for “${esc(q)}”</h2><p class="muted">Looking up articles...</p></div>`;try{const data=await wikiRequest({list:'search',srsearch:q,srlimit:12});if(!windows.has('browser')||currentTab().id!==id)return;const results=data.query?.search||[];v.innerHTML=`<div class="panel-pad scroll" style="max-width:760px;margin:0 auto"><div class="eyebrow">WIKIPEDIA READER</div><h2 class="section-title" style="margin:9px 0 6px">Results for “${esc(q)}”</h2><p class="muted">${results.length} article${results.length!==1?'s':''} found · <a href="https://en.wikipedia.org/wiki/Special:Search?search=${encodeURIComponent(q)}" target="_blank" rel="noopener noreferrer">View all on Wikipedia ↗</a></p>${results.map(x=>`<button class="wiki-result" data-article="${esc(x.title)}"><strong>${esc(x.title)}</strong><div class="muted small" style="margin-top:5px">Read article in Golden Gate OS →</div></button>`).join('')||'<p>No results. Try another search.</p>'}</div>`;v.querySelectorAll('[data-article]').forEach(el=>el.onclick=()=>browserGoEntry(el.dataset.article,'wiki-article',el.dataset.article))}catch(e){v.innerHTML=`<div class="empty-state">${ic('wifi')}<h3>Unable to connect to Wikipedia</h3><p>Check your connection or use the full web search in an external tab.</p><button class="secondary-button" id="wiki-external-search" style="margin:12px">Open web search ↗</button></div>`;v.querySelector('#wiki-external-search').onclick=()=>openExternal('https://www.google.com/search?q='+encodeURIComponent(q))}}
async function renderWikiArticle(v,title,id){v.innerHTML='<div class="panel-pad"><p>Loading article...</p></div>';try{const data=await wikiRequest({prop:'extracts|pageimages',explaintext:'1',exsectionformat:'plain',piprop:'thumbnail',pithumbsize:'600',titles:title});if(!windows.has('browser')||currentTab().id!==id)return;const x=data.query?.pages?.[0];if(!x||x.missing)throw Error('Article not found');v.innerHTML=`<article class="panel-pad scroll" style="max-width:840px;margin:auto;user-select:text"><div class="eyebrow">FROM WIKIPEDIA · READER MODE</div><h1 style="font-size:34px;letter-spacing:-1px;margin:9px 0 11px">${esc(x.title)}</h1><a href="https://en.wikipedia.org/wiki/${encodeURIComponent(x.title.replaceAll(' ','_'))}" target="_blank" rel="noopener noreferrer">Original article ↗</a><div class="divider" style="margin:18px 0"></div>${x.thumbnail?.source?`<img src="${esc(x.thumbnail.source)}" style="max-height:220px;max-width:50%;object-fit:contain;float:right;border-radius:12px;margin:2px 0 20px 22px" alt="">`:''}<div class="article-text">${esc((x.extract||'No text was returned for this article.').slice(0,35000))}</div></article>`}catch{v.innerHTML=`<div class="empty-state"><h3>Could not load this article</h3><p>Try visiting it on Wikipedia instead.</p><button class="primary-button" id="wiki-visit">Open original ↗</button></div>`;v.querySelector('#wiki-visit').onclick=()=>openExternal('https://en.wikipedia.org/wiki/'+encodeURIComponent(title))}}
/* Calendar */
let events=load('events',[]),calendarMonth=new Date(new Date().getFullYear(),new Date().getMonth(),1),selectedDay=new Date().toISOString().slice(0,10);
function dayKey(y,m,d){return `${y}-${String(m+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`}
function renderCalendar(){const b=body('calendar');if(!b)return;const y=calendarMonth.getFullYear(),m=calendarMonth.getMonth(),first=(new Date(y,m,1).getDay()+6)%7,days=new Date(y,m+1,0).getDate(),today=dayKey(new Date().getFullYear(),new Date().getMonth(),new Date().getDate());let cells='';for(let i=0;i<42;i++){const day=i-first+1,dt=new Date(y,m,day),k=dayKey(dt.getFullYear(),dt.getMonth(),dt.getDate()),n=events.filter(e=>e.date===k).length;cells+=`<button class="calendar-day ${day<1||day>days?'other-month':''} ${k===today?'today':''} ${k===selectedDay?'selected':''}" data-date="${k}"><span class="day-number">${dt.getDate()}</span><span style="display:flex;gap:3px;flex-wrap:wrap">${Array(Math.min(n,4)).fill('<i class="event-dot"></i>').join('')}</span></button>`}const selectedEvents=events.filter(e=>e.date===selectedDay);b.innerHTML=`<div class="window-toolbar"><button class="icon-button" id="cal-prev" title="Previous month">${ic('chevronLeft')}</button><button class="icon-button" id="cal-next" title="Next month">${ic('chevronRight')}</button><strong class="grow" style="font-size:16px">${calendarMonth.toLocaleDateString(undefined,{month:'long',year:'numeric'})}</strong><button class="secondary-button" id="cal-today">Today</button><button class="primary-button" id="cal-add">${ic('plus','tiny-icon')} Event</button></div><div class="window-pane"><main class="app-main scroll panel-pad"><div class="calendar-grid">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(d=>`<div class="calendar-dayname">${d}</div>`).join('')}${cells}</div></main><aside class="app-sidebar" style="width:235px;padding:18px 14px"><div class="eyebrow">SCHEDULE</div><h3 style="font-size:17px;letter-spacing:-.4px;margin:9px 0 17px">${new Date(selectedDay+'T12:00:00').toLocaleDateString(undefined,{month:'short',day:'numeric',weekday:'long'})}</h3>${selectedEvents.length?selectedEvents.map(e=>`<div class="event-list-item"><div style="width:5px;height:29px;background:var(--accent);border-radius:8px"></div><span class="grow">${esc(e.title)}</span><button class="icon-button" data-delete-event="${e.id}" title="Delete">${ic('x','tiny-icon')}</button></div>`).join(''):'<div class="muted small">Nothing scheduled.<br>Enjoy the open space.</div>'}</aside></div>`;b.querySelector('#cal-prev').onclick=()=>{calendarMonth=new Date(y,m-1,1);renderCalendar()};b.querySelector('#cal-next').onclick=()=>{calendarMonth=new Date(y,m+1,1);renderCalendar()};b.querySelector('#cal-today').onclick=()=>{calendarMonth=new Date();calendarMonth.setDate(1);selectedDay=dayKey(new Date().getFullYear(),new Date().getMonth(),new Date().getDate());renderCalendar()};b.querySelector('#cal-add').onclick=()=>{const n=askName('Event name:','New event');if(n){events.push({id:uid(),date:selectedDay,title:n});store('events',events);renderCalendar();notify('Event added')}};b.querySelectorAll('[data-date]').forEach(el=>el.onclick=()=>{selectedDay=el.dataset.date;const d=new Date(selectedDay+'T12:00:00');if(d.getMonth()!==m){calendarMonth=new Date(d.getFullYear(),d.getMonth(),1)}renderCalendar()});b.querySelectorAll('[data-delete-event]').forEach(el=>el.onclick=()=>{events=events.filter(x=>x.id!==el.dataset.deleteEvent);store('events',events);renderCalendar()})}
/* Calculator */
let calcExpression='0';function renderCalculator(){const b=body('calculator');if(!b)return;const keys=[['AC','special'],['±','special'],['%','special'],['÷','operator'],['7',''],['8',''],['9',''],['×','operator'],['4',''],['5',''],['6',''],['−','operator'],['1',''],['2',''],['3',''],['+','operator'],['0','zero'],['.',''],['=','operator']];b.innerHTML=`<div style="flex:1;overflow:auto;display:flex;align-items:center;justify-content:center;padding:18px;background:linear-gradient(160deg,#eceef24a,#f6f8fc16)"><div class="calc-shell"><div class="small" style="opacity:.65;letter-spacing:1.5px">CALCULATOR</div><div class="calc-screen" id="calc-display">${esc(calcExpression)}</div><div class="calc-grid">${keys.map(([txt,cls])=>`<button class="calc-key ${cls}" data-key="${esc(txt)}">${esc(txt)}</button>`).join('')}</div></div></div>`;b.querySelectorAll('[data-key]').forEach(el=>el.onclick=()=>calculatorKey(el.dataset.key))}
function calculatorKey(k){if(k==='AC')calcExpression='0';else if(k==='±')calcExpression=calcExpression.startsWith('−')?calcExpression.slice(1):'−'+calcExpression;else if(k==='%'){const n=Number(calcExpression.replace('−','-'));if(Number.isFinite(n))calcExpression=String(n/100)}else if(k==='='){try{const expression=calcExpression.replace(/×/g,'*').replace(/÷/g,'/').replace(/−/g,'-');if(!/^[\d.\s()+*\/-]+$/.test(expression))throw Error();const result=Function('"use strict";return ('+expression+')')();if(!Number.isFinite(result))throw Error();calcExpression=String(Number(result.toPrecision(10)))}catch{calcExpression='Error'}}else if(['+','−','×','÷'].includes(k)){if(calcExpression==='Error')calcExpression='0';calcExpression+=k}else if(k==='.'){calcExpression+='.'}else{calcExpression=(calcExpression==='0'||calcExpression==='Error')?k:calcExpression+k}const display=body('calculator')?.querySelector('#calc-display');if(display){display.textContent=calcExpression;display.style.fontSize=calcExpression.length>16?'28px':'44px'}}
